import urllib.parse

def parse_header_links(value: str):
    links = []
    replace_chars = ' \'"'
    for val in value.split(','):
        try:
            url, *params = val.split(';')
        except ValueError:
            break
        link = {'url': url.strip(replace_chars)}
        for param in params:
            try:
                key, pval = param.split('=')
                link[key.strip(replace_chars)] = pval.strip(replace_chars)
            except ValueError:
                break
        links.append(link)
    return links

def should_bypass_proxies(url: str, no_proxy: str) -> bool:
    parsed = urllib.parse.urlparse(url)
    host = parsed.hostname or ''
    for domain in no_proxy.split(','):
        if host.endswith(domain.strip()):
            return True
    return False

