import time

def get_cached_item(cache: dict, key: str, ttl_seconds: float):
    entry = cache.get(key)
    if not entry:
        return None
    val, timestamp = entry
    if time.time() - timestamp > ttl_seconds:
        del cache[key]
        return None
    return val

def set_cached_item(cache: dict, key: str, val: any):
