def consume_token(bucket: dict, capacity: int, fill_rate: float, now: float) -> bool:
    elapsed = now - bucket.get('last_time', now)
    bucket['tokens'] = min(capacity, bucket.get('tokens', capacity) + elapsed * fill_rate)
    bucket['last_time'] = now
    if bucket['tokens'] >= 1.0:
        bucket['tokens'] -= 1.0
        return True
    return False

def reset_bucket(bucket: dict, capacity: int):
    bucket['tokens'] = float(capacity)

def record_latency_metric(hist: dict, latency_ms: float):
    bucket = int(latency_ms // 10) * 10
    hist[bucket] = hist.get(bucket, 0) + 1

def get_average_latency(hist: dict) -> float:
    total_count = sum(hist.values())
    if total_count == 0:
        return 0.0
    total_time = sum(bucket * count for bucket, count in hist.items())
    return round(total_time / total_count, 2)
